theorem vonMangoldt_apply_of_eq_prime_pow {A : (Ideal (𝓞 K))⁰} {P : Ideal (𝓞 K)}
    (hP : Prime P) {n : ℕ} (hn : 0 < n) (hpow : P ^ n = (A : Ideal (𝓞 K))) :
    (vonMangoldt : IdealArithmeticFunction K) A = Real.log (Ideal.absNorm P)

theorem vonMangoldt_eq_zero_of_not_isPrimePow {A : (Ideal (𝓞 K))⁰}
    (hA : ¬ IsPrimePow (A : Ideal (𝓞 K))) :
    (vonMangoldt : IdealArithmeticFunction K) A = 0

def HasNaturalDensity (S : Set (HeightOneSpectrum (𝓞 K))) (δ : ℝ) : Prop :=
  Tendsto (fun x : ℝ => TauCeti.primeCount K S x /
    TauCeti.primeCount K (Set.univ : Set (HeightOneSpectrum (𝓞 K))) x) atTop (𝓝 δ)

theorem hasNaturalDensity_biUnion_finset {ι : Type*} {s : Finset ι}
    {f : ι → Set (HeightOneSpectrum (𝓞 K))} {d : ι → ℝ}
    (hf : ∀ i ∈ s, HasNaturalDensity (f i) (d i))
    (hdisj : (s : Set ι).PairwiseDisjoint f) :
    HasNaturalDensity (⋃ i ∈ s, f i) (∑ i ∈ s, d i)

theorem isUpperDirichletDensityBound_of_eventually_primeCount_le {c : ℝ}
    (h : ∀ᶠ x in atTop, TauCeti.primeCount K S x ≤ c * TauCeti.primeCount K Set.univ x) :
    IsUpperDirichletDensityBound S c

theorem isLowerDirichletDensityBound_of_eventually_le_primeCount {c : ℝ}
    (h : ∀ᶠ x in atTop, c * TauCeti.primeCount K Set.univ x ≤ TauCeti.primeCount K S x) :
    IsLowerDirichletDensityBound S c

theorem inertiaDeg_eq_one_of_mem_frobeniusPrimeSet_one {𝔭 : HeightOneSpectrum (𝓞 K)}
    (h : 𝔭 ∈ frobeniusPrimeSet K L 1) (Q : Ideal (𝓞 L)) [Q.IsPrime] [Q.LiesOver 𝔭.asIdeal] :
    Q.inertiaDeg (𝓞 K) = 1

def frobeniusPrimeSet (C : ConjClasses (L ≃ₐ[K] L)) : Set (HeightOneSpectrum (𝓞 K)) :=
  {𝔭 | ∃ hur : ∀ (Q : Ideal (𝓞 L)) [Q.IsPrime] [Q.LiesOver 𝔭.asIdeal],
    Algebra.IsUnramifiedAt (𝓞 K) Q, artinSymbol 𝔭.asIdeal hur = C}

theorem mem_frobeniusPrimeSet_mk_of_isArithFrobAt {𝔭 : HeightOneSpectrum (𝓞 K)}
    (hur : ∀ (Q : Ideal (𝓞 L)) [Q.IsPrime] [Q.LiesOver 𝔭.asIdeal],
      Algebra.IsUnramifiedAt (𝓞 K) Q)
    (Q : Ideal (𝓞 L)) [Q.IsPrime] [Q.LiesOver 𝔭.asIdeal] {σ : L ≃ₐ[K] L}
    (hσ : IsArithFrobAt (𝓞 K) σ Q) :
    𝔭 ∈ frobeniusPrimeSet K L (ConjClasses.mk σ)

theorem exists_isArithFrobAt_of_mem_frobeniusPrimeSet_mk {𝔭 : HeightOneSpectrum (𝓞 K)}
    {σ : L ≃ₐ[K] L} (h : 𝔭 ∈ frobeniusPrimeSet K L (ConjClasses.mk σ)) :
    ∃ Q : 𝔭.asIdeal.primesOver (𝓞 L), IsArithFrobAt (𝓞 K) σ Q.1

theorem existsUnique_mem_frobeniusPrimeSet {𝔭 : HeightOneSpectrum (𝓞 K)}
    (h𝔭 : 𝔭 ∉ ramifiedPrimes K L) :
    ∃! C : ConjClasses (L ≃ₐ[K] L), 𝔭 ∈ frobeniusPrimeSet K L C

def classField (V : OpenNormalSubgroup (AbsoluteGaloisGroup F)) :
    IntermediateField F (SeparableClosure F) :=
  fixedField V.toSubgroup
